int commandCatalogExtractKeys(commandCatalog *cat, struct redisCommand *cmd, robj **argv, int argc, getKeysResult *result) {
    commandCatalogBindKeyCommand(cat, cmd, argv, argc, result);
    if (cmd->flags & CMD_MODULE_GETKEYS) {
        cat->keys_movable = 1;
        cat->keys_count = moduleGetCommandKeysViaAPI(cmd,argv,argc,result);
        return cat->keys_count;
    } else if (!(cmd->flags & CMD_MODULE) && cmd->getkeys_proc) {
        cat->keys_movable = 1;
        cat->keys_count = cmd->getkeys_proc(cmd,argv,argc,result);
        return cat->keys_count;
    } else {
        cat->keys_movable = 0;
        return commandCatalogExtractLegacyRange(cat,cmd,argv,argc,result);
    }
}

int commandCatalogExtractGeneric(commandCatalog *cat, int storeKeyOfs, int keyCountOfs, int firstKeyOfs, int keyStep,
                    robj **argv, int argc, getKeysResult *result) {
    int i, num, *keys;
    cat->keys_argv = argv;
    cat->keys_argc = argc;
    cat->keys_out = result;
    cat->keys_store_ofs = storeKeyOfs;
    cat->keys_count_ofs = keyCountOfs;
    cat->keys_first = firstKeyOfs;
    cat->keys_step = keyStep;

    num = atoi(argv[keyCountOfs]->ptr);
    /* Sanity check. Don't return any key if the command is going to
     * reply with syntax error. (no input keys). */
    if (num < 1 || num > (argc - firstKeyOfs)/keyStep) {
        result->numkeys = 0;
        cat->keys_count = 0;
        return 0;
    }

    int numkeys = storeKeyOfs ? num + 1 : num;
    keys = commandCatalogPrepareKeys(cat, result, numkeys);
    result->numkeys = numkeys;
    cat->keys_count = numkeys;

    /* Add all key positions for argv[firstKeyOfs...n] to keys[] */
    for (i = 0; i < num; i++) {
        keys[i] = firstKeyOfs+(i*keyStep);
        cat->last_key_index = keys[i];
    }

    if (storeKeyOfs) {
        keys[num] = storeKeyOfs;
        cat->last_key_index = storeKeyOfs;
    }
    return result->numkeys;
}

